import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
demo_in=G['Demo pair 1 input']; demo_out=G['Demo pair 1 output']; test=G['Test input']
def fill_diag(g):
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    for i in range(H):
        for j in range(W):
            if g[i][j]==0: continue
            for k in range(1,H):
                ni,nj=(i+k)%H,(j+k)%W
                if out[ni][nj]==0: out[ni][nj]=g[i][j]
    return out
r=fill_diag(test)
for row in r: print(' '.join(map(str,row)))
print('demo match:', fill_diag(demo_in)==demo_out)

def transform(g):
    H,W=len(g),len(g[0])
    dirs=[(dr,dc) for dr in(-1,0,1) for dc in(-1,0,1) if (dr,dc)!=(0,0)]
    def score(d):
        dr,dc=d; s=0
        for i in range(H):
            for j in range(W):
                if g[i][j] and g[(i-dr)%H][(j-dc)%W]==g[i][j]: s+=1
        return s
    d=max(dirs,key=score)
    dr,dc=d
    out=[row[:] for row in g]
    for i in range(H):
        for j in range(W):
            if out[i][j]: continue
            k=1
            while k<=max(H,W):
                v=g[(i-k*dr)%H][(j-k*dc)%W]
                if v: out[i][j]=v; break
                k+=1
    return out
print('demo:', transform(demo_in)==demo_out)
r=transform(test)
for row in r: print(' '.join(map(str,row)))

